import unittest


def is_palindrome(s):
    return s == s[::-1]


class TestIsPalindrome(unittest.TestCase):
    """Unit tests for the is_palindrome function."""

    def test_empty_string(self):
        """Test with an empty string."""
        self.assertTrue(is_palindrome(""))

    def test_single_character(self):
        """Test with a single character string."""
        self.assertTrue(is_palindrome("a"))

    def test_two_character_palindrome(self):
        """Test with a two character palindrome."""
        self.assertTrue(is_palindrome("aa"))

    def test_two_character_non_palindrome(self):
        """Test with a two character non-palindrome."""
        self.assertFalse(is_palindrome("ab"))

    def test_odd_length_palindrome(self):
        """Test with an odd length palindrome."""
        self.assertTrue(is_palindrome("aba"))

    def test_even_length_palindrome(self):
        """Test with an even length palindrome."""
        self.assertTrue(is_palindrome("abba"))

    def test_odd_length_non_palindrome(self):
        """Test with an odd length non-palindrome."""
        self.assertFalse(is_palindrome("abc"))

    def test_even_length_non_palindrome(self):
        """Test with an even length non-palindrome."""
        self.assertFalse(is_palindrome("abcd"))

    def test_mixed_case(self):
        """Test with mixed case strings (case-sensitive)."""
        self.assertFalse(is_palindrome("Abba"))
        self.assertTrue(is_palindrome("Abba".lower()))

    def test_with_spaces(self):
        """Test with strings containing spaces."""
        self.assertFalse(is_palindrome("a b"))
        self.assertTrue(is_palindrome("a a"))

    def test_with_special_characters(self):
        """Test with strings containing special characters."""
        self.assertTrue(is_palindrome("!@#$%$#@!"))
        self.assertFalse(is_palindrome("!@#$%"))

    def test_long_palindrome(self):
        """Test with a longer palindrome."""
        long_palindrome = "racecar"
        self.assertTrue(is_palindrome(long_palindrome))

    def test_long_non_palindrome(self):
        """Test with a longer non-palindrome."""
        long_non_palindrome = "racecars"
        self.assertFalse(is_palindrome(long_non_palindrome))


if __name__ == '__main__':
